$skillPath = 'D:\Temp\combat-motion-eval-e1dsw32j\candidate\skills\combat-director\SKILL.md'
$outPath = 'D:\Temp\combat-motion-eval-e1dsw32j\results\candidate-T01'
$answer = '8秒，日间自然光，固定全景。两名成年虚构刀客分立石桥两端，相向静静对峙，目光始终观察彼此；两人仅以手指轻微收放调整握柄，双脚原地不动，刀身保持低垂。全程不交手、不切镜，无台词，只有桥下流水声。'
if ($answer.Length -gt 120) { throw 'Answer exceeds 120 characters.' }
New-Item -ItemType Directory -Path $outPath -Force | Out-Null
[System.IO.File]::WriteAllText((Join-Path $outPath 'answer.md'), $answer, [System.Text.UTF8Encoding]::new($false))
[pscustomobject]@{
 task_original = [System.IO.File]::ReadAllText($taskPath)
 read_files = @($taskPath, $skillPath) | ForEach-Object { [pscustomobject]@{ path = $_; sha256 = (Get-FileHash -LiteralPath $_ -Algorithm SHA256).Hash } }
 answer_characters = $answer.Length
 answer_path = (Join-Path $outPath 'answer.md')
} | ConvertTo-Json -Depth 5

